----------------------------------------
-- Ingesta Plana --
----------------------------------------


-- Se crea una vista para la carga masiva de créditos.
-- Se excluye IdCredito porque es una columna IDENTITY
-- y SQL Server la genera automáticamente.

CREATE VIEW Operaciones.VistaCargaCreditos AS
SELECT
    IdCliente,
    IdVehiculo,
    MontoCapital,
    TasaInteresMensual,
    Estado,
    FechaDesembolso
FROM Operaciones.Creditos;

-- Se utiliza BULK INSERT para importar 2,000 créditos
-- desde un archivo de texto separado por pipes (|).
-- FIELDTERMINATOR indica el separador entre columnas.
-- ROWTERMINATOR indica el salto de línea entre registros.
-- Inicialmente el archivo fue colocado en /tmp,
-- pero SQL Server no pudo acceder correctamente a esa ruta.

-- Se movió el archivo a una carpeta autorizada para BULK INSERT:
-- /tmp/bulkload/

-- Finalmente, la carga se ejecutó usando la nueva ruta del archivo.

BULK INSERT Operaciones.VistaCargaCreditos
FROM '/tmp/bulkload/Fase2_2000_Creditos_Completo.txt'
WITH (
    FIELDTERMINATOR = '|',
    ROWTERMINATOR = '0x0a'
);


---------------------------------------
-- Reporte de Riesgo Acumulado --
----------------------------------------

SELECT 
    Estado,
    SUM(MontoCapital) AS TotalCapitalPrestado,
    AVG(TasaInteresMensual) AS PromedioTasaInteres
FROM Operaciones.Creditos
GROUP BY Estado;


---------------------------------------
-- Reporte de Concentración Vehicular --
----------------------------------------

SELECT 
    V.Marca,
    COUNT(*) AS CantidadPrestamos
FROM Operaciones.Creditos C
INNER JOIN Garantias.Vehiculos V
    ON C.IdVehiculo = V.IdVehiculos
GROUP BY V.Marca
HAVING COUNT(*) > 50;

---------------------------------------
-- Análisis de Extremos --
----------------------------------------

SELECT 
    MAX(MontoCapital) AS PrestamoMayor,
    MIN(MontoCapital) AS PrestamoMenor
FROM Operaciones.Creditos;



